<script>
document.addEventListener('DOMContentLoaded', function() {
    const thumbnails = document.querySelectorAll('.cxo-studio__thumbnail');
    const videoContainer = document.getElementById('cxo-studio__video-container');
    const closeButton = document.getElementById('cxo-studio__close-button');
    const spinner = document.getElementById('cxo-studio__spinner');
    const overlay = document.getElementById('cxo-studio__overlay');


    thumbnails.forEach(function(thumbnail) {
        thumbnail.addEventListener('click', function() {
            const videoId = this.getAttribute('data-video-id');
            const selectedVideo = document.getElementById(videoId);


            videoContainer.querySelectorAll('video').forEach(function(video) {
                video.style.display = 'none';
            });


            selectedVideo.style.display = 'inline';


            // Append overlay and video container to body
            document.body.appendChild(overlay);
            document.body.appendChild(videoContainer);


            overlay.style.display = 'block';
            videoContainer.style.display = 'block';
            spinner.style.display = 'block';


            selectedVideo.addEventListener('playing', function() {
                spinner.style.display = 'none';
            }, { once: true });


            selectedVideo.play();
        });
    });


    closeButton.addEventListener('click', function(event) {
        event.stopPropagation();
        closeVideoContainer();
    });


    overlay.addEventListener('click', function(event) {
        event.stopPropagation();
        closeVideoContainer();
    });


    function closeVideoContainer() {
        videoContainer.style.display = 'none';
        overlay.style.display = 'none';
        videoContainer.querySelectorAll('video').forEach(function(video) {
            video.pause();
        });
        spinner.style.display = 'none';


        // Optionally, remove from body if needed
        // document.body.removeChild(overlay);
        // document.body.removeChild(videoContainer);
    }
});


</script>
